#!/usr/bin/env bash
# Round 9: every speech qualification and full-set reference rescored under SIM attention v1 (one evaluator digest),
# then winners and truncation D_refs re-derived from the new campaign qualification. Run from the repository root.
set -u
cd "$(dirname "$0")/../.."
PY=.venv/bin/python
C=results/l20x/campaign
OUT=$C/sim_v2
mkdir -p $OUT/fullq_scored_v3 $OUT/dref_v3
log() { echo "[$(date +%T)] $*"; }
log "qualification v3"
$PY -m evals.campaign qualify --sweep $C/qualify_seed0 --sweep $C/qualify_seed1 --sweep $C/qualify_seed2 --sweep $C/qualify_seed1_rerun1 --gpu 2 --gpu 3 --out $C/qualification_v3; log "qualify rc=$?"
$PY -m evals.campaign select --qualification $C/qualification_v3/campaign_qualification.json --sweep $C/tune_gpu1 --sweep $C/tune_gpu2 --sweep $C/tune_gpu3 --out $C/winners_v3.json; log "select rc=$?"
$PY -m evals.campaign dref --winners $C/winners_v3.json --role truncation --concurrency 32 --sweep $C/fullq_c32_seed0 --sweep $C/fullq_c32_seed0_rest --sweep $C/fullq_c32_seed1 --sweep $C/fullq_c32_seed2 --out-dir $OUT/dref_v3; log "dref c32 rc=$?"
$PY -m evals.campaign dref --winners $C/winners_v3.json --role truncation --concurrency 1 --sweep $C/fullq_c1_seed0 --sweep $C/fullq_c1_seed1 --sweep $C/fullq_c1_seed2 --out-dir $OUT/dref_v3; log "dref c1 rc=$?"
lane2() {
  log "score vllm-omni_minicpmo_4_5_turn_mrv2_h200_mps_mps-on_ecae2534b6b1_c32.json gpu2"; $PY -m evals.speech.suite score --scope final --gpu 2 --out $OUT/fullq_scored_v3/vllm-omni_minicpmo_4_5_turn_mrv2_h200_mps_mps-on_ecae2534b6b1_c32.json --d-ref $OUT/dref_v3/dref_truncation_c32.json --cell results/l20x/campaign/fullq_c32_seed0_rest/00_vllm-omni_minicpmo_4_5_turn_mrv2_h200_mps-mps-on_ecae2534b6b1_c32 --cell results/l20x/campaign/fullq_c32_seed1/04_vllm-omni_minicpmo_4_5_turn_mrv2_h200_mps-mps-on_ecae2534b6b1_c32 --cell results/l20x/campaign/fullq_c32_seed2/04_vllm-omni_minicpmo_4_5_turn_mrv2_h200_mps-mps-on_ecae2534b6b1_c32 >> $OUT/fullq_scored_v3/score_gpu2.log 2>&1; log "vllm-omni_minicpmo_4_5_turn_mrv2_h200_mps_mps-on_ecae2534b6b1_c32.json rc=$?"
  log "score sglang-omni_speech_mm32k_4ebf4e2bdd31_c32.json gpu2"; $PY -m evals.speech.suite score --scope final --gpu 2 --out $OUT/fullq_scored_v3/sglang-omni_speech_mm32k_4ebf4e2bdd31_c32.json --d-ref $OUT/dref_v3/dref_truncation_c32.json --cell /workspace/cgzheng/cgzheng/qwen3_omni/results/l20x/campaign/fullq_c32_seed0_rest/02_sglang-omni_speech-mm32k_4ebf4e2bdd31_c32 --cell /workspace/cgzheng/cgzheng/qwen3_omni/results/l20x/campaign/fullq_c32_seed1/05_sglang-omni_speech-mm32k_4ebf4e2bdd31_c32 --cell /workspace/cgzheng/cgzheng/qwen3_omni/results/l20x/campaign/fullq_c32_seed2/01_sglang-omni_speech-mm32k_4ebf4e2bdd31_c32 >> $OUT/fullq_scored_v3/score_gpu2.log 2>&1; log "sglang-omni_speech_mm32k_4ebf4e2bdd31_c32.json rc=$?"
  log "score sglang-omni_speech_mps-on_ac0e44a46d2d_c32.json gpu2"; $PY -m evals.speech.suite score --scope final --gpu 2 --out $OUT/fullq_scored_v3/sglang-omni_speech_mps-on_ac0e44a46d2d_c32.json --d-ref $OUT/dref_v3/dref_truncation_c32.json --cell /workspace/cgzheng/cgzheng/qwen3_omni/results/l20x/campaign/fullq_c32_seed0_rest/01_sglang-omni_speech-mps-on_ac0e44a46d2d_c32 --cell /workspace/cgzheng/cgzheng/qwen3_omni/results/l20x/campaign/fullq_c32_seed1/00_sglang-omni_speech-mps-on_ac0e44a46d2d_c32 --cell /workspace/cgzheng/cgzheng/qwen3_omni/results/l20x/campaign/fullq_c32_seed2/00_sglang-omni_speech-mps-on_ac0e44a46d2d_c32 >> $OUT/fullq_scored_v3/score_gpu2.log 2>&1; log "sglang-omni_speech_mps-on_ac0e44a46d2d_c32.json rc=$?"
  log "score vllm-omni_minicpmo_4_5_turn_mps_mps-on_9901f000524d_c32.json gpu2"; $PY -m evals.speech.suite score --scope final --gpu 2 --out $OUT/fullq_scored_v3/vllm-omni_minicpmo_4_5_turn_mps_mps-on_9901f000524d_c32.json --d-ref $OUT/dref_v3/dref_truncation_c32.json --cell /workspace/cgzheng/cgzheng/qwen3_omni/results/l20x/campaign/fullq_c32_seed0_rest/03_vllm-omni_minicpmo_4_5_turn_mps-mps-on_9901f000524d_c32 --cell /workspace/cgzheng/cgzheng/qwen3_omni/results/l20x/campaign/fullq_c32_seed1/02_vllm-omni_minicpmo_4_5_turn_mps-mps-on_9901f000524d_c32 --cell /workspace/cgzheng/cgzheng/qwen3_omni/results/l20x/campaign/fullq_c32_seed2/06_vllm-omni_minicpmo_4_5_turn_mps-mps-on_9901f000524d_c32 >> $OUT/fullq_scored_v3/score_gpu2.log 2>&1; log "vllm-omni_minicpmo_4_5_turn_mps_mps-on_9901f000524d_c32.json rc=$?"
}
